 static Dictionary<string,DateTime> recoveryTimes=new Dictionary<string,DateTime>();static Dictionary<string,string> recoveryHashes=new Dictionary<string,string>();
 static void SaveRecovery(Dictionary<string,object> state,string mode){
  if(!state.ContainsKey("project")||state["project"]==null)return;
  string encoded=json.Serialize(state["project"]),hash;using(var sha=System.Security.Cryptography.SHA256.Create())hash=Convert.ToBase64String(sha.ComputeHash(Encoding.UTF8.GetBytes(encoded)));
  DateTime last;if(recoveryHashes.ContainsKey(mode)&&recoveryHashes[mode]==hash)return;if(recoveryTimes.TryGetValue(mode,out last)&&(DateTime.UtcNow-last).TotalSeconds<120)return;
  var project=state["project"] as Dictionary<string,object>;if(project==null)return;
  string folder=Path.Combine(root,"Recovery");Directory.CreateDirectory(folder);DateTime now=DateTime.UtcNow;string id=mode+"-"+now.ToString("yyyyMMddHHmmssfff")+"-"+Guid.NewGuid().ToString("N"),path=Path.Combine(folder,id+".json"),temp=path+".tmp";
  File.WriteAllText(temp,json.Serialize(new{title=project.ContainsKey("title")?Convert.ToString(project["title"]):"Untitled",created=now.ToString("o"),project=project}),new UTF8Encoding(false));File.Move(temp,path);recoveryHashes[mode]=hash;recoveryTimes[mode]=now;
  var files=new List<string>(Directory.GetFiles(folder,mode+"-*.json"));files.Sort(StringComparer.Ordinal);while(files.Count>20){File.Delete(files[0]);files.RemoveAt(0);}
 }
 static string RememberProjectFile(string path){path=Path.GetFullPath(path);lock(sessionLock){knownProjectFiles.Add(path);File.WriteAllText(Path.Combine(root,"project-files.json"),json.Serialize(new List<string>(knownProjectFiles)),new UTF8Encoding(false));}return path;}

 [DllImport("user32.dll")]static extern IntPtr GetForegroundWindow();
 [DllImport("user32.dll",CharSet=CharSet.Unicode)]static extern int GetWindowText(IntPtr window,StringBuilder text,int length);
 [DllImport("user32.dll")]static extern bool IsWindowVisible(IntPtr window);
 sealed class PickerWindow:IWin32Window{readonly IntPtr handle;public PickerWindow(IntPtr value){handle=value;}public IntPtr Handle{get{return handle;}}}
 static DialogResult ShowProjectDialog(FileDialog dialog){
  // A native dialog must be owned by the editor, not by a hidden launcher-thread form.
  IntPtr foreground=GetForegroundWindow();var title=new StringBuilder(512);GetWindowText(foreground,title,title.Capacity);
  string caption=title.ToString();
  if(foreground!=IntPtr.Zero&&IsWindowVisible(foreground)&&caption.IndexOf("StarForge",StringComparison.OrdinalIgnoreCase)>=0&&caption.IndexOf("Launcher",StringComparison.OrdinalIgnoreCase)<0)
   return dialog.ShowDialog(new PickerWindow(foreground));
  // Detached panels or a focus change may leave no editor HWND available. Keep a
  // transparent topmost owner visible for the full dialog lifetime; Hide loses its z-order.
  using(var owner=new Form{Width=1,Height=1,ShowInTaskbar=false,TopMost=true,Opacity=0,FormBorderStyle=FormBorderStyle.None,StartPosition=FormStartPosition.CenterScreen}){
   owner.Show();owner.Activate();owner.BringToFront();return dialog.ShowDialog(owner);
  }
 }

 [DllImport("user32.dll")]static extern bool EnumWindows(WindowCallback callback,IntPtr param);
 delegate bool WindowCallback(IntPtr window,IntPtr param);
 [DllImport("user32.dll")]static extern uint GetWindowThreadProcessId(IntPtr window,out uint process);
 [DllImport("user32.dll")]static extern bool PostMessage(IntPtr window,uint message,IntPtr wParam,IntPtr lParam);
 static void CloseForUpdate(){
  try{string profile=Path.Combine(root,".browser-profile");var owned=new HashSet<uint>();using(var query=new ManagementObjectSearcher("SELECT ProcessId,CommandLine FROM Win32_Process WHERE Name='msedge.exe'"))foreach(ManagementObject row in query.Get()){string command=Convert.ToString(row["CommandLine"]);if(command.IndexOf(profile,StringComparison.OrdinalIgnoreCase)>=0)owned.Add(Convert.ToUInt32(row["ProcessId"]));}
   EnumWindows((window,param)=>{uint pid;GetWindowThreadProcessId(window,out pid);if(owned.Contains(pid)&&IsWindowVisible(window))PostMessage(window,0x10,IntPtr.Zero,IntPtr.Zero);return true;},IntPtr.Zero);
  }catch{}Environment.Exit(0);
 }
 static string PickSaveProject(string folder,string name,string extension){string picked=null;Exception failure=null;var thread=new Thread(()=>{try{using(var dialog=new SaveFileDialog{Title="Save project as",InitialDirectory=folder,RestoreDirectory=true,FileName=name,DefaultExt=extension.TrimStart('.'),AddExtension=true,OverwritePrompt=true,Filter="StarForge project (*"+extension+")|*"+extension}){if(ShowProjectDialog(dialog)==DialogResult.OK)picked=dialog.FileName;}}catch(Exception error){failure=error;}});thread.SetApartmentState(ApartmentState.STA);thread.Start();thread.Join();if(failure!=null)throw failure;return picked;}
 static void ReplyBytes(Stream stream,int status,string mime,byte[] body){byte[] head=Encoding.ASCII.GetBytes("HTTP/1.1 "+status+" OK\r\nContent-Type: "+mime+"\r\nContent-Length: "+body.Length+"\r\nConnection: close\r\n\r\n");stream.Write(head,0,head.Length);stream.Write(body,0,body.Length);}
 static void Reply(Stream stream,int status,string mime,string text){byte[] body=Encoding.UTF8.GetBytes(text),head=Encoding.ASCII.GetBytes("HTTP/1.1 "+status+" OK\r\nContent-Type: "+mime+"; charset=utf-8\r\nContent-Length: "+body.Length+"\r\nCache-Control: no-store\r\nConnection: close\r\n\r\n");stream.Write(head,0,head.Length);stream.Write(body,0,body.Length);}
